def can_broadcast(a, b):
    for x, y in zip(reversed(a), reversed(b)):
        if x != y and x != 1 and y != 1:
            return False
    return True
print(can_broadcast((3, 2), (3, 1)), can_broadcast((3, 2), (2,)))
print(can_broadcast((3, 2), (4,)), can_broadcast((3, 1, 4), (4,)))
# True True
# False True

def duplicate_keys(rows, key):
    seen, dup = set(), set()
    for r in rows:
        k = r[key]
        if k in seen: dup.add(k)
        seen.add(k)
    return sorted(dup, key=str)
orders = [{'cid': 1}, {'cid': 2}, {'cid': 1}]
customers = [{'cid': 1}, {'cid': 1}]
print(duplicate_keys(orders, 'cid'), duplicate_keys(customers, 'cid'))
print(duplicate_keys([], 'cid'))
# [1] [1]
# []

def validate(payload):
    errors = []
    if not isinstance(payload, dict):
        return ['body must be a JSON object']
    text = payload.get('text')
    if not isinstance(text, str) or not text.strip():
        errors.append('text: required non-empty string')
    if 'top_k' in payload:
        k = payload['top_k']
        if not isinstance(k, int) or isinstance(k, bool) or not 1 <= k <= 10:
            errors.append('top_k: int in 1..10')
    return errors
print(validate({'text': 'hi'}), validate({'text': ' '}))
print(validate({'text': 'hi', 'top_k': 99}), validate('nope'))
# [] ['text: required non-empty string']
# ['top_k: int in 1..10'] ['body must be a JSON object']

import time
def with_retry(fn, attempts=3, base=0.01):
    for i in range(attempts):
        try:
            return fn(i)
        except TimeoutError:
            if i == attempts - 1:
                raise
            time.sleep(base * (2 ** i))

calls = []
def flaky(i):
    calls.append(i)
    if i < 2:
        raise TimeoutError('upstream timeout')
    return 'ok'
print(with_retry(flaky), calls)

def always_down(i):
    raise TimeoutError('down')
try:
    with_retry(always_down, attempts=2, base=0.001)
except TimeoutError as e:
    print('gave up:', e)
# ok [0, 1, 2]
# gave up: down
